// Parse incoming timesheet date and format it
const timesheetDate = $input.first().json.timesheetDate;

if (!timesheetDate) {
  throw new Error('timesheetDate is required (format: M/D/YYYY or MM/DD/YYYY)');
}

// Parse date
const parts = timesheetDate.split('/');
if (parts.length !== 3) {
  throw new Error('Invalid date format. Use M/D/YYYY');
}

const month = parseInt(parts[0]).toString().padStart(2, '0');
const day = parseInt(parts[1]).toString().padStart(2, '0');
const year = parts[2];

const formattedDate = `${year}.${month}.${day}`;
const folderName = formattedDate;
const basePath = '/home/node/.openclaw/workspace/projects/n8n/timesheet/output';
const outputPath = `${basePath}/${folderName}`;
const templatePath = '/home/node/.openclaw/workspace/projects/n8n/timesheet/n8n-workflows/templates';

return {
  json: {
    timesheetDate,
    formattedDate,
    folderName,
    outputPath,
    templatePath,
    basePath
  }
};

const fs = require('fs');
const path = require('path');

const outputPath = $input.first().json.outputPath;

try {
  // Create directory if it doesn't exist
  if (!fs.existsSync(outputPath)) {
    fs.mkdirSync(outputPath, { recursive: true });
  }

  return {
    json: {
      success: true,
      folderCreated: true,
      path: outputPath
    }
  };
} catch (error) {
  throw new Error(`Failed to create folder: ${error.message}`);
}

const fs = require('fs');
const path = require('path');

const outputPath = $input.first().json.outputPath;
const templatePath = $input.first().json.templatePath;
const formattedDate = $input.first().json.formattedDate;

const wordTemplatePath = `${templatePath}/RossNanton-Invoice-yyyy.mm.dd.docx`;
const wordOutputPath = `${outputPath}/RossNanton-Invoice-${formattedDate}.docx`;

try {
  fs.copyFileSync(wordTemplatePath, wordOutputPath);
  return {
    json: {
      success: true,
      fileCopied: 'Word',
      sourcePath: wordTemplatePath,
      outputPath: wordOutputPath
    }
  };
} catch (error) {
  throw new Error(`Failed to copy Word template: ${error.message}`);
}

const fs = require('fs');
const path = require('path');

const outputPath = $input.first().json.outputPath;
const templatePath = $input.first().json.templatePath;
const formattedDate = $input.first().json.formattedDate;

const excelTemplatePath = `${templatePath}/RossNanton-Timesheet-yyyy.mm.dd.xlsx`;
const excelOutputPath = `${outputPath}/RossNanton-Timesheet-${formattedDate}.xlsx`;

try {
  fs.copyFileSync(excelTemplatePath, excelOutputPath);
  return {
    json: {
      success: true,
      fileCopied: 'Excel',
      sourcePath: excelTemplatePath,
      outputPath: excelOutputPath,
      excelFilePath: excelOutputPath
    }
  };
} catch (error) {
  throw new Error(`Failed to copy Excel template: ${error.message}`);
}

const xlsx = require('xlsx');
const fs = require('fs');

const excelFilePath = $input.last().json.excelFilePath || $input.first().json.excelFilePath;
const timesheetDate = $input.first().json.timesheetDate;

if (!excelFilePath) {
  throw new Error('Excel file path not provided');
}

if (!timesheetDate) {
  throw new Error('Timesheet date not provided');
}

try {
  // Read the Excel file
  const workbook = xlsx.readFile(excelFilePath);
  const worksheet = workbook.Sheets[workbook.SheetNames[0]];

  // Update cell E8 with the timesheet date
  worksheet['E8'] = { v: timesheetDate, t: 's' };

  // Write the file back
  xlsx.writeFile(workbook, excelFilePath);

  return {
    json: {
      success: true,
      fileUpdated: 'Excel (Cell E8)',
      filePath: excelFilePath,
      cellE8Updated: timesheetDate
    }
  };
} catch (error) {
  throw new Error(`Failed to update Excel file: ${error.message}`);
}

// Compile final response
const updateResult = $input.first().json;
const allInputs = $input.all();

let timesheetDate = updateResult.cellE8Updated || updateResult.timesheetDate;
let folderName = updateResult.folderName;
let formattedDate = updateResult.formattedDate;
let outputPath = updateResult.outputPath;

// Fallback to looking through all inputs for required values
if (!timesheetDate || !folderName) {
  for (let i = 0; i < allInputs.length; i++) {
    if (allInputs[i].json.timesheetDate && !timesheetDate) {
      timesheetDate = allInputs[i].json.timesheetDate;
    }
    if (allInputs[i].json.folderName && !folderName) {
      folderName = allInputs[i].json.folderName;
    }
    if (allInputs[i].json.formattedDate && !formattedDate) {
      formattedDate = allInputs[i].json.formattedDate;
    }
    if (allInputs[i].json.outputPath && !outputPath) {
      outputPath = allInputs[i].json.outputPath;
    }
  }
}

return {
  json: {
    status: 'success',
    message: 'Timesheet setup completed successfully',
    details: {
      timesheetDate: timesheetDate,
      folderName: folderName,
      outputPath: outputPath,
      filesCreated: [
        `RossNanton-Invoice-${formattedDate}.docx`,
        `RossNanton-Timesheet-${formattedDate}.xlsx (Cell E8 updated: ${timesheetDate})`
      ]
    }
  }
};
